#!/usr/bin/env node
/**
 * Pull `manifest.json` from the public automation-forge repository into
 * `data/manifest.json`.
 *
 * The manifest is *generated by CI* from the plugin register, the descriptors
 * and the published releases — it is the one place that knows every version
 * that exists, what it weighs, its sha256, and its release notes. This wiki
 * must never restate any of that in prose; it reads it.
 *
 * The copy is committed rather than fetched at build time so that a build is
 * reproducible offline and a manifest change shows up as a reviewable diff
 * rather than silently altering a published page. The cost is that it goes
 * stale, which is what the scheduled refresh in CI is for.
 *
 * Usage:
 *   node tools/sync-manifest.mjs              fetch from GitHub
 *   node tools/sync-manifest.mjs <local path> copy from a local clone
 */
import { writeFile, readFile, mkdir } from 'node:fs/promises'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const REMOTE =
  'https://raw.githubusercontent.com/AutomationForgeHQ/automation-forge/main/manifest.json'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const target = resolve(root, 'data/manifest.json')

const from = process.argv[2]

let raw
if (from) {
  raw = await readFile(resolve(from), 'utf8')
  console.log(`read ${from}`)
} else {
  const res = await fetch(REMOTE)
  if (!res.ok) {
    console.error(`manifest fetch failed: ${res.status} ${res.statusText}`)
    process.exit(1)
  }
  raw = await res.text()
  console.log(`fetched ${REMOTE}`)
}

const parsed = JSON.parse(raw)
if (parsed.schemaVersion !== 1) {
  console.error(
    `manifest schemaVersion is ${parsed.schemaVersion}, this site reads 1 — ` +
      `check lib/manifest.ts before bumping.`,
  )
  process.exit(1)
}

await mkdir(dirname(target), { recursive: true })
await writeFile(target, JSON.stringify(parsed, null, 2) + '\n', 'utf8')

const versions = parsed.plugins.reduce((n, p) => n + p.versions.length, 0)
console.log(
  `wrote data/manifest.json — ${parsed.sets.length} sets, ` +
    `${parsed.plugins.length} plugins, ${versions} published versions, ` +
    `generated ${parsed.generatedAt}`,
)
